import pandas as pd, tabula, json, re
def clean(df):
 for c in ['Salary','Years','Score']:
  if c in df.columns:
   df[c] = df[c].astype(str).str.replace(',','').astype(float)
 return df
try:
 curr = clean(pd.read_excel('/root/employees_current.xlsx'))
 tabs = tabula.read_pdf('/root/employees_backup.pdf', pages='all', stream=True)
 back_rows = []
 for df in tabs:
  for _, r in df.iterrows():
   v = [str(x) for x in r.values if pd.notna(x)]
   if v and re.match(r'EMP\d{5}', v[0]) and len(v)>=9: back_rows.append(v[:9])
 back = clean(pd.DataFrame(back_rows, columns=['ID','First','Last','Dept','Position','Salary','Years','Location','Score']))
 del_ids = sorted(list(set(back.ID) - set(curr.ID)))
 mod = []
 common = sorted(list(set(back.ID) & set(curr.ID)))
 for eid in common:
  br, cr = back[back.ID==eid].iloc[0], curr[curr.ID==eid].iloc[0]
  for col in ['First','Last','Dept','Position','Salary','Years','Location','Score']:
   bv, cv = br[col], cr[col]
   if col in ['Salary','Years']:
    bv, cv = int(bv), int(cv)
   if bv != cv:
    mod.append({"id":eid, "field":col, "old_value":bv, "new_value":cv})
 with open('/root/diff_report.json','w') as f: json.dump({"deleted_employees":del_ids, "modified_employees":mod}, f, indent=2)
 print("Success")
except Exception as e: print(e)
